import java.util.*;

class Solution {
    public int getIntersectionNode(int[] next, int startA, int startB) {
        int p = startA, q = startB;
        while (p != q) {
            p = (p == -1) ? startB : next[p];  // fell off A: continue on B
            q = (q == -1) ? startA : next[q];  // fell off B: continue on A
        }
        return p;   // junction marker, or -1 if the trails never meet
    }
}

